import json

import pytest
from fastapi.testclient import TestClient

from app import server
from app.cad_agent import CadGenerationError
from app.mesh_engine import export_mesh_data, generate_sample_mesh

client = TestClient(server.app)


def fake_result(**_kwargs):
    exported = export_mesh_data(generate_sample_mesh("cube"))
    return {
        "code": "mesh = trimesh.creation.box()",
        "explanation": "Generated by test-model (openai)",
        "log": "ok",
        "stats": exported["stats"],
        "obj_data": exported["obj_data"],
        "stl_bytes": exported["stl_bytes"],
    }


@pytest.fixture(autouse=True)
def no_token(monkeypatch):
    monkeypatch.delenv("STUDIO_ACCESS_TOKEN", raising=False)


def test_models_endpoint_lists_xai():
    body = client.get("/api/models").json()
    assert any(m["provider"] == "xai" for m in body["models"])


def test_generate_and_export_roundtrip(monkeypatch):
    monkeypatch.setattr(server, "generate_cad_model", fake_result)
    res = client.post("/api/generate", json={"prompt": "a cube", "provider": "openai"})
    assert res.status_code == 200
    body = res.json()
    stl = client.get(f"/api/export/{body['session_id']}/stl")
    assert stl.status_code == 200
    assert stl.headers["content-type"] == "application/sla"
    assert client.get("/api/export/does-not-exist/stl").status_code == 404


def test_untrusted_base_url_is_rejected_before_any_call():
    res = client.post(
        "/api/generate",
        json={
            "prompt": "x",
            "provider": "self-hosted",
            "base_url": "http://attacker.example/v1",
        },
    )
    assert res.status_code == 400
    assert "not allowed" in res.json()["detail"]


def test_generation_failure_maps_to_502(monkeypatch):
    def failing(**_kwargs):
        raise CadGenerationError("LLM call failed: boom", "log line")

    monkeypatch.setattr(server, "generate_cad_model", failing)
    res = client.post("/api/generate", json={"prompt": "a cube"})
    assert res.status_code == 502
    assert res.json()["detail"]["message"] == "LLM call failed: boom"


def test_empty_prompt_rejected():
    assert client.post("/api/generate", json={"prompt": ""}).status_code == 422
    assert client.post("/api/generate", json={"prompt": "   "}).status_code == 400


def test_cross_origin_requests_are_not_allowed_by_default():
    pre = client.options(
        "/api/generate",
        headers={
            "Origin": "https://evil.example",
            "Access-Control-Request-Method": "POST",
            "Access-Control-Request-Headers": "content-type",
        },
    )
    assert "access-control-allow-origin" not in pre.headers


def test_access_token_enforced_when_configured(monkeypatch):
    monkeypatch.setenv("STUDIO_ACCESS_TOKEN", "s3cret")
    monkeypatch.setattr(server, "generate_cad_model", fake_result)
    assert client.post("/api/generate", json={"prompt": "a cube"}).status_code == 401
    ok = client.post(
        "/api/generate", json={"prompt": "a cube"}, headers={"X-Studio-Token": "s3cret"}
    )
    assert ok.status_code == 200


def _sse_events(text: str) -> list[dict]:
    return [
        json.loads(line[6:]) for line in text.split("\n\n") if line.startswith("data: ")
    ]


def test_stream_emits_logs_then_complete(monkeypatch):
    def fake_with_logs(**kwargs):
        kwargs["log_callback"]("step 1")
        return fake_result()

    monkeypatch.setattr(server, "generate_cad_model", fake_with_logs)
    res = client.post("/api/generate_stream", json={"prompt": "a cube"})
    events = _sse_events(res.text)
    assert events[0] == {"type": "log", "message": "step 1"}
    assert events[-1]["type"] == "complete"


def test_stream_emits_error_event(monkeypatch):
    def failing(**_kwargs):
        raise CadGenerationError("nope", "log")

    monkeypatch.setattr(server, "generate_cad_model", failing)
    events = _sse_events(
        client.post("/api/generate_stream", json={"prompt": "a cube"}).text
    )
    assert events[-1]["type"] == "error"
    assert events[-1]["message"] == "nope"


def test_session_store_is_bounded():
    store = server.SessionStore(max_items=2, ttl_seconds=60)
    first = store.put({"n": 1})
    store.put({"n": 2})
    store.put({"n": 3})
    assert store.get(first) is None
